function layout(route, title, description, body) {
  const { lang, key } = route;
  const safeTitleText = sanitizeVisibleText(title);
  const safeDescriptionText = sanitizeVisibleText(description);
  const canonical = `${BASE_URL}${routeUrlFor(lang, route)}`;
  const jsonLd = JSON.stringify(schemaGraph(route, safeTitleText, safeDescriptionText)).replaceAll("<", "\\u003c");
  const robots = robotsMeta(route);
  const preloadImage = imagePreloadForRoute(route);
  return `<!doctype html>
<html lang="${lang}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(safeTitleText)}</title>
  <meta name="description" content="${escapeHtml(safeDescriptionText)}">
  <meta name="robots" content="${robots}">
  <link rel="canonical" href="${canonical}">
  <link rel="icon" href="/favicon.ico" sizes="any">
  <link rel="icon" type="image/png" sizes="32x32" href="/brand/favicon-32x32.png">
  <link rel="icon" type="image/png" sizes="16x16" href="/brand/favicon-16x16.png">
  <link rel="apple-touch-icon" sizes="180x180" href="/brand/apple-touch-icon.png">
  <link rel="manifest" href="/site.webmanifest">
  ${preloadImage}
  ${hreflangForRoute(route)}
  <meta property="og:title" content="${escapeHtml(safeTitleText)}">
  <meta property="og:description" content="${escapeHtml(safeDescriptionText)}">
  <meta property="og:image" content="${BRAND_OG_IMAGE_URL}">
  <meta property="og:image:width" content="1200">
  <meta property="og:image:height" content="630">
  <meta property="og:image:alt" content="CAS AURUM gold crowned monogram logo">
  <meta property="og:url" content="${canonical}">
  <meta property="og:type" content="website">
  <meta property="og:locale" content="${langs[lang].locale}">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="${escapeHtml(safeTitleText)}">
  <meta name="twitter:description" content="${escapeHtml(safeDescriptionText)}">
  <meta name="twitter:image" content="${BRAND_TWITTER_IMAGE_URL}">
  <meta name="theme-color" content="#15120e">
  <meta name="msapplication-TileColor" content="#050403">
  <meta name="msapplication-TileImage" content="/brand/mstile-150x150.png">
  ${analyticsHead()}
  <script type="application/ld+json">${jsonLd}</script>
  <link rel="stylesheet" href="${SITE_CSS_PATH}">
</head>
<body>
  <a class="skip" href="#main">${escapeHtml(localized("Skip to content", lang))}</a>
  ${header(route)}
  <main id="main">${body}</main>
  ${footer(route)}
  <script>window.__CAS_AURUM_SEO_PAGE__=${JSON.stringify(seoTrackingPayload(route)).replaceAll("<", "\\u003c")};</script>
  <script defer src="${CLIENT_JS_PATH}"></script>
  ${route.key === "planner" || route.key === "quickEstimate" ? `${route.key === "planner" ? `<script defer src="https://unpkg.com/three@0.160.0/build/three.min.js"></script>` : ""}<script defer src="${PLANNER_JS_PATH}"></script>` : ""}
</body>
</html>`;
}

function header(route) {
  const t = copy[route.lang];
  const nav = seoHeaderLinks(route.lang);
  const ctaHref = route.lang === "uk" ? "/design-concept#start-design-concept" : `${urlFor(route.lang, "designConcept")}#start-design-concept`;
  const ctaLabel = route.lang === "uk" ? "Надіслати запит" : (solutionLabels[route.lang] || solutionLabels.en).startProject;
  return `<header class="site-header">
    <a class="brand track" data-event="cta_clicked" href="${urlFor(route.lang, "home")}" aria-label="CAS AURUM home"><img class="brand-lockup" src="/brand/logo-lockup-small.webp" width="156" height="125" alt="CAS AURUM"></a>
    <button class="menu-button" type="button" aria-controls="nav" aria-expanded="false">${escapeHtml(localized("Menu", route.lang))}</button>
    <nav id="nav" aria-label="Primary">${nav.map((item) => `<a href="${item.href}">${escapeHtml(item.label)}</a>`).join("")}</nav>
    <a class="header-cta track" data-event="start_project_clicked" href="${ctaHref}">${escapeHtml(ctaLabel)}</a>
  </header>`;
}

function footer(route) {
  const t = copy[route.lang];
  if (route.lang === "uk") {
    return `<footer class="site-footer">
      <div><a class="brand" href="/uk"><img class="brand-lockup footer-brand-lockup" src="/brand/logo-lockup-small.webp" width="156" height="125" alt="CAS AURUM"></a><p>Індивідуальні інтер'єрні рішення, дизайн-концепти, TV-стіни, кухні, меблі та стінові панелі.</p></div>
      <div><h3>Почати</h3><a href="/design-concept#start-design-concept">Надіслати запит</a><a href="/quick-project-estimate">Швидка оцінка проєкту</a><a href="/gallery">Галерея</a><a href="/">Продовжити англійською</a></div>
      <div><h3>${escapeHtml(localized("Languages", route.lang))}</h3>${languageSwitcher(route)}<a href="/privacy-policy">Політика конфіденційності</a><a href="/terms-of-use">Умови використання</a></div>
    </footer>`;
  }
  const seo = seoFooterColumns(route.lang, route);
  return `<footer class="site-footer">
    <div><a class="brand" href="${urlFor(route.lang, "home")}"><img class="brand-lockup footer-brand-lockup" src="/brand/logo-lockup-small.webp" width="156" height="125" alt="CAS AURUM"></a><p>${escapeHtml(t.home.hero)}</p></div>
    ${seo.map((column) => `<div><h3>${escapeHtml(column.title)}</h3>${column.links.map((item) => `<a href="${item.href}">${escapeHtml(item.label)}</a>`).join("")}</div>`).join("")}
    <div><h3>${escapeHtml(localized("Languages", route.lang))}</h3>${languageSwitcher(route)}<a href="${urlFor(route.lang, "privacy")}">${escapeHtml(copy[route.lang].legal.privacy[0])}</a><a href="${urlFor(route.lang, "terms")}">${escapeHtml(copy[route.lang].legal.terms[0])}</a></div>
  </footer>`;
}

